source='''from collections import deque


def transform(grid):
    """Color cells in each nonzero component whose 3x3 neighborhood matches a marker."""
    original = [row[:] for row in grid]
    output = [row[:] for row in grid]
    height, width = len(original), len(original[0])
    seen = set()

    for r in range(height):
        for c in range(width):
            if original[r][c] == 0 or (r, c) in seen:
                continue
            component = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                x, y = queue.popleft()
                component.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < height and 0 <= ny < width
                            and original[nx][ny] != 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        queue.append((nx, ny))

            markers = [(x, y, original[x][y]) for x, y in component
                       if original[x][y] > 1]
            for mr, mc, color in markers:
                pattern = tuple(
                    tuple(int(0 <= mr + dr < height and 0 <= mc + dc < width
                              and original[mr + dr][mc + dc] != 0)
                          for dc in (-1, 0, 1))
                    for dr in (-1, 0, 1)
                )
                for x, y in component:
                    if original[x][y] != 1:
                        continue
                    candidate = tuple(
                        tuple(int(0 <= x + dr < height and 0 <= y + dc < width
                                  and original[x + dr][y + dc] != 0)
                              for dc in (-1, 0, 1))
                        for dr in (-1, 0, 1)
                    )
                    if candidate == pattern:
                        output[x][y] = color
    return output
'''
